/**
 * Shared UI symbols — the single source for every icon in the app.
 *
 * ONE symbol source, so unrelated controls cannot drift into different icon
 * styles (decided with the user after the first mixed set): every path below is
 * taken verbatim from
 *
 *   google/material-design-icons -> symbols/android/<name>/materialsymbolsrounded/<name>_<size>px.xml
 *
 * i.e. **Material Symbols (the new Material Design Symbols set), Rounded
 * style, weight 400, grade 0** — the same library, style and weight for every
 * icon. This is the successor of the older "Material Icons" set: never mix in a
 * glyph from that library or from any other icon set, and never change the
 * weight. The app icon (favicon) is the one symbol that does not live here — it
 * is a brand mark, drawn as a file in apps/web/public/favicon.svg — but it
 * follows these same rules; see docs/CODING_CONVENTIONS.md.
 *
 * **Optical size (docs/DESIGN.md §4.5).** The family draws every symbol at
 * several optical sizes, and each one is a drawing of its own rather than a
 * scale: at the smaller sizes the shape's ink span shrinks so the stroke keeps
 * its weight. A symbol therefore ships the drawing of every size the app
 * renders it at, and the call site names it through `optical`:
 *
 *   14 and 18px (--icon-sm / --icon-md) -> the 20px drawing (PATHS_20)
 *   24px (--icon-size)                  -> the 24px drawing (PATHS_24, default)
 *   above 24px (the 42px cloche)        -> the 40px drawing (PATHS_40)
 *
 * The rendered size still comes from CSS (docs/DESIGN.md §4.3/§4.5) — `optical`
 * only selects which drawing fills that box, so the two must agree: a symbol the
 * CSS renders at 18px is asked for `optical={20}`. A symbol drawn only at 24px
 * carries no second drawing, because it is never rendered at another size.
 *
 * **The grid.** The family draws on its native 960 x 960 grid and every path
 * below uses it, with one documented exception: a source file that itself uses a
 * smaller grid (the sparkle: 24- and 20-unit) keeps that file's own viewBox
 * rather than being hand-rescaled, so no path is ever converted. The drawables'
 * y values run 0..960 top-down, so a negative y origin would place every glyph
 * outside the visible box. `fill="currentColor"` makes each glyph follow the
 * text color of its button or tag.
 *
 * Rules:
 * - an icon is always decorative (`aria-hidden`): it either sits next to a
 *   visible label or its button carries an `aria-label`;
 * - the only fill change is the star's own filled/unfilled pair (the same
 *   symbol's `star` and `star_fill1` drawings); every other icon is unfilled, and
 *   a state is never shown by a glyph from another style or weight;
 * - a path is never edited by hand: a glyph that has to change is re-fetched
 *   from the source above, so this file stays verifiable against upstream.
 */

/** The optical size a drawing was cut for (docs/DESIGN.md §4.5). */
export type OpticalSize = 20 | 24 | 40;

/** The class name of the symbol's `<svg>` (undefined = sized by its context). */
interface IconProps {
  className?: string;
  /**
   * The drawing to draw; it must match the size the CSS gives the symbol
   * (§4.5): 20 for a symbol rendered at 14 or 18px, 40 for the 42px
   * room-service cloche, 24 (the default) for a standalone symbol.
   */
  optical?: OpticalSize;
}

/** The family's native grid; a symbol may carry its own instead (see above). */
const GRID = '0 0 960 960';

/** Attributes every symbol shares.
 *
 * The explicit `width`/`height` are the fallback that keeps a symbol usable
 * without any CSS: an SVG with only a `viewBox` falls back to the replaced
 * element default of 300 x 150 px, which would blow up a button and push its
 * label out of sight (that is exactly what happened when the icons were first
 * swapped in). 24 px is the ladder's inline icon size; component rules such as
 * `.button-icon` (18 px) or `.tag-icon` (14 px) override it by class. */
const ICON_PROPS = {
  width: 24,
  height: 24,
  'aria-hidden': true,
  focusable: 'false',
} as const;

