/**
 * The cross as a raw SVG string, for the one place where the DOM is built
 * imperatively (the removable inline artifacts in StepEditor). It is assembled
 * from the same tables and the same grid as the CloseIcon component, at the size
 * that control renders it (18px → the 20px drawing, §4.5), so the two can never
 * drift apart. It is a complete `<svg>`: a bare `<path>` injected with
 * `innerHTML` is not inside an SVG document and draws nothing at all.
 */
export const CLOSE_ICON_SVG = `<svg viewBox="${GRID}" width="24" height="24" aria-hidden="true" focusable="false"><path d="${PATHS_20.close?.d ?? PATHS_24.close}" fill="currentColor" /></svg>`;

/** Cross — close, dismiss or remove. */
export function CloseIcon({ className, optical }: IconProps) {
  return <Glyph name="close" className={className} optical={optical} />;
}

